INSERT OR IGNORE INTO templates (
  id, title, description, pinned, pin_order, category, targets_json, sections_json
) VALUES
  ('default-initial-screen', 'Initial Screen', 'Initial recruiter screen. Use only what was said in the conversation or notes. Never invent statements, numbers, employers or outcomes. If a topic was not discussed, write Not discussed; that is not evidence against the candidate. Do not score the candidate or give a hire or no-hire verdict. A section with little content can be a single line.', 0, NULL, 'Recruiting', '["Recruiter","Talent Partner","Hiring Manager"]', '[{"title":"Interview Context","description":"Role, company and candidate background, only as stated in the conversation or notes."},{"title":"Key Takeaways","description":"The most important points from the conversation, stated factually."},{"title":"Evidence Against Role Requirements","description":"For each role requirement mentioned, give its status (Verified, Partially verified, Unresolved or Concern) and the supporting evidence from the conversation. If no requirements were stated, write No role requirements were provided."},{"title":"Candidate Examples and Signals","description":"Specific experience and examples the candidate gave. Include contradictions only if the candidate or interviewer actually stated them."},{"title":"Logistics","description":"Availability, location, notice period and compensation expectations, only if stated."},{"title":"Evidence Gaps","description":"Topics that were not covered or remain unclear. Not discussed is not a negative signal."},{"title":"Suggested Follow-up","description":"Questions to ask next, based on the gaps and concerns above."},{"title":"Cautious Next Action","description":"One tentative next step for the recruiter to consider, such as another interview or a reference check. No hire or no-hire verdict and no score."}]'),
  ('default-technical-interview', 'Technical Interview', 'Technical interview. Use only what was said in the conversation or notes. Never invent statements, numbers, employers or outcomes. If a topic was not discussed, write Not discussed; that is not evidence against the candidate. Do not score the candidate or give a hire or no-hire verdict. A section with little content can be a single line.', 0, NULL, 'Recruiting', '["Interviewer","Hiring Manager","Engineering Manager"]', '[{"title":"Interview Context","description":"Role, company and candidate background, only as stated in the conversation or notes."},{"title":"Key Takeaways","description":"The most important points from the conversation, stated factually."},{"title":"Evidence Against Role Requirements","description":"For each role requirement mentioned, give its status (Verified, Partially verified, Unresolved or Concern) and the supporting evidence from the conversation. If no requirements were stated, write No role requirements were provided."},{"title":"Technical Topics and Candidate Answers","description":"Each technical topic discussed, what the candidate said or demonstrated, and how they approached any problem. Judge correctness only where the interviewer did so in the conversation."},{"title":"Concerns and Contradictions","description":"Concerns raised by the interviewer or inconsistencies in the candidate statements. If none were stated, write None stated."},{"title":"Evidence Gaps","description":"Topics that were not covered or remain unclear. Not discussed is not a negative signal."},{"title":"Suggested Follow-up","description":"Questions to ask next, based on the gaps and concerns above."},{"title":"Cautious Next Action","description":"One tentative next step for the recruiter to consider, such as another interview or a reference check. No hire or no-hire verdict and no score."}]'),
  ('default-behavioural-interview', 'Behavioural Interview', 'Behavioural interview. Use only what was said in the conversation or notes. Never invent statements, numbers, employers or outcomes. If a topic was not discussed, write Not discussed; that is not evidence against the candidate. Do not score the candidate or give a hire or no-hire verdict. A section with little content can be a single line.', 0, NULL, 'Recruiting', '["Interviewer","Hiring Manager","Recruiter"]', '[{"title":"Interview Context","description":"Role, company and candidate background, only as stated in the conversation or notes."},{"title":"Key Takeaways","description":"The most important points from the conversation, stated factually."},{"title":"Evidence Against Role Requirements","description":"For each role requirement mentioned, give its status (Verified, Partially verified, Unresolved or Concern) and the supporting evidence from the conversation. If no requirements were stated, write No role requirements were provided."},{"title":"Examples Shared","description":"Each example the candidate gave: situation, their own actions and the result, only as stated. Write Not stated for any part that was not said."},{"title":"Competencies Discussed","description":"Competencies the interviewer asked about and the evidence given for each. Do not infer traits that were not discussed."},{"title":"Concerns and Contradictions","description":"Concerns raised by the interviewer or inconsistencies in the candidate statements. If none were stated, write None stated."},{"title":"Evidence Gaps","description":"Topics that were not covered or remain unclear. Not discussed is not a negative signal."},{"title":"Suggested Follow-up","description":"Questions to ask next, based on the gaps and concerns above."},{"title":"Cautious Next Action","description":"One tentative next step for the recruiter to consider, such as another interview or a reference check. No hire or no-hire verdict and no score."}]');
